package com.example.leavemanagement.policy.api;
import com.example.leavemanagement.policy.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/leave-types") public class AdminPolicyController {private final LeavePolicyAdministrationService service;public AdminPolicyController(LeavePolicyAdministrationService s){service=s;} @GetMapping public List<LeavePolicyAdministrationService.Detail> list(){return service.list();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public LeavePolicyAdministrationService.Detail create(@Valid @RequestBody TypeCreate c){return service.createType(new LeavePolicyAdministrationService.TypeCreate(c.code(),c.name(),c.description(),c.active()));} @PatchMapping("/{id}") public LeavePolicyAdministrationService.Detail update(@PathVariable UUID id,@Valid @RequestBody TypeUpdate c){return service.updateType(id,new LeavePolicyAdministrationService.TypeUpdate(c.code(),c.name(),c.description(),c.active(),c.expectedVersion()));} @PostMapping("/{id}/policies") @ResponseStatus(HttpStatus.CREATED) public LeavePolicyAdministrationService.PolicyView policy(@PathVariable UUID id,@Valid @RequestBody Policy c){return service.createPolicy(id,new LeavePolicyAdministrationService.PolicyCommand(c.effectiveFrom(),c.effectiveTo(),c.tracksBalance(),c.allowsHalfDay(),c.weeklyOffTreatment(),c.holidayTreatment(),c.rejectionCommentRequired(),c.cancellationCutoffDays(),c.weeklyOffDays(),c.expectedVersion()));} public record TypeCreate(@NotBlank @Size(max=40)String code,@NotBlank @Size(max=120)String name,@Size(max=500)String description,boolean active){} public record TypeUpdate(@NotBlank @Size(max=40)String code,@NotBlank @Size(max=120)String name,@Size(max=500)String description,boolean active,@NotNull @Min(0)Long expectedVersion){} public record Policy(@NotNull LocalDate effectiveFrom,LocalDate effectiveTo,boolean tracksBalance,boolean allowsHalfDay,@NotBlank String weeklyOffTreatment,@NotBlank String holidayTreatment,boolean rejectionCommentRequired,@Min(0)int cancellationCutoffDays,@NotNull List<Integer> weeklyOffDays,@NotNull @Min(0)Long expectedVersion){} }
